// backend/scripts/backfillBridgeDirection.js
const path = require('path');
require('dotenv').config({ path: path.join(__dirname, '../.env') });
const mongoose = require('mongoose');
const connectDB = require('../config/db');
const Expenditure = require('../models/Expenditure');

const backfillBridgeDirection = async () => {
  try {
    await connectDB();
    console.log('Running backfill for bridgeDirection on legacy auto-credits...');

    // Find all legacy bridge records from Phase 7B that lack bridgeDirection or autoGenerated
    const filter = {
      $or: [
        { linkedPaycheckId: { $ne: null } },
        { linkedGoldId: { $ne: null } },
        { linkedCertificateId: { $ne: null } },
      ],
      $or: [
        { bridgeDirection: null },
        { bridgeDirection: { $exists: false } },
        { autoGenerated: { $ne: true } },
      ],
    };

    const result = await Expenditure.updateMany(
      {
        $and: [
          {
            $or: [
              { linkedPaycheckId: { $ne: null } },
              { linkedGoldId: { $ne: null } },
              { linkedCertificateId: { $ne: null } },
            ],
          },
          {
            $or: [
              { bridgeDirection: null },
              { bridgeDirection: { $exists: false } },
              { autoGenerated: { $ne: true } },
            ],
          },
        ],
      },
      {
        $set: {
          autoGenerated: true,
          bridgeDirection: 'inflow',
        },
      }
    );

    console.log(`Backfill complete: updated ${result.modifiedCount} expenditures to bridgeDirection: 'inflow' and autoGenerated: true.`);
  } catch (err) {
    console.error('Error during backfill:', err);
    process.exit(1);
  } finally {
    await mongoose.connection.close();
    console.log('Database connection closed.');
  }
};

if (require.main === module) {
  backfillBridgeDirection();
}

module.exports = backfillBridgeDirection;

